        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def valid_points(items):
        out = []
        for it in items or []:
            p = pos(it)
            if p is not None:
                out.append(p)
        return out

    def nearest(items, src):
        best = None
        best_d = None
        for p in valid_points(items):
            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(items, src):
        best = None
        best_d = None
        for p in valid_points(items):
            d = manhattan(src, p)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    def clamp_point(p, w, h):
        x, y = p
        if w:
            if x < 0:
                x = 0
            elif x >= w:
                x = w - 1
        if h:
            if y < 0:
                y = 0
            elif y >= h:
                y = h - 1
        return (x, y)

    env = observation.get("environment_name", "") or ""
    self_pos = pos(observation.get("self_position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or self_pos
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    role = observation.get("self_role", "") or ""

    # Shared fallback anchors
    center = clamp_point((w // 2, h // 2), w, h) if w and h else self_pos
    corners = []
