        corners = [clamp_point((0, 0), w, h), clamp_point((0, h - 1), w, h),
                   clamp_point((w - 1, 0), w, h), clamp_point((w - 1, h - 1), w, h)]

    if env == "pursuit_evasion":
        if role == "evader":
            target = farthest(corners or [center], opp_pos)
            if target is None:
                return step_away(self_pos, opp_pos)
